1	import {
2	  ConflictException,
3	  Injectable,
4	  NotFoundException,
5	  PayloadTooLargeException,
6	} from '@nestjs/common';
7	import { ConfigService } from '@nestjs/config';
8	import { InjectDataSource, InjectRepository } from '@nestjs/typeorm';
9	import { createHash } from 'node:crypto';
10	import { DataSource, LessThan, QueryFailedError, Repository } from 'typeorm';
11	import { User } from '../../auth/entities/user.entity';
12	import { IdentityService } from '../../auth/services/identity.service';
13	import {
14	  acquireAdvisoryLock,
15	  advisoryLockKey,
16	  resolveAdvisoryLockTimeoutMs,
17	  setAdvisoryLockTimeout,
18	} from '../../common/advisory-lock';
19	import { Clock } from '../../common/clock';
20	import { positiveIntConfig } from '../../common/config-int';
21	import { MailboxMessage } from '../entities/mailbox-message.entity';
22	
23	/** Spec-fixed hard bound on the sealed blob (blueprint/api.md: <= ~8 KB). */
24	const MAX_BLOB_BYTES = 8192;
25	
26	/** 90-day unacked TTL, aligned with record EOLs (blueprint/api.md, Mailbox). */
27	const TTL_MS = 90 * 24 * 60 * 60 * 1000;
28	
29	/** Rows deleted per global-sweep batch; via MAILBOX_SWEEP_BATCH_SIZE. */
30	const DEFAULT_SWEEP_BATCH_SIZE = 1000;
31	
32	/**
33	 * Internal "don't loop forever" guard on batches per sweep run — not a per-deploy
34	 * knob. The loop already drains on `deleted < batchSize`; this only caps a
35	 * pathological backlog, leaving any remainder for the next scheduled run.
36	 */
37	export const SWEEP_MAX_BATCHES = 1000;
38	
39	/**
40	 * Canonical RFC 4122 UUID — the form `gen_random_uuid()` mints for the id
41	 * column. Ids are always server-minted uuids, so any other shape can never
42	 * name a row; matching this before the ack delete keeps a malformed id from
43	 * reaching the `uuid`-typed column (Postgres would raise 22P02 → a 500).
44	 */
45	const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
46	
47	export interface PostMessageInput {
48	  recipientPublicKey: string;
49	  blob: string;
50	  idempotencyKey: string;
51	}
52	
53	export interface PostMessageResult {
54	  id: string;
55	}
56	
57	export interface PolledMessage {
58	  id: string;
59	  receivedAt: string;
60	  blob: string;
61	}
62	
63	/**
64	 * The integrity-untrusted mailbox (blueprint/api.md, Mailbox).
65	 *
66	 * Zero-knowledge: blobs are opaque HPKE-sealed bytes — never decoded, never
67	 * logged, never signature-checked (that is client-side). Retention is bounded
68	 * until ack: a per-recipient pending cap (reject-new) and a lazily enforced
69	 * 90-day TTL, both hard-deletes. Determinism is injected — post time and TTL
70	 * cutoffs come from the Clock, never `Date.now()`.
71	 */
72	@Injectable()
73	export class MailboxService {
74	  private readonly pendingCap: number;
75	  private readonly pollLimit: number;
76	  private readonly lockTimeoutMs: number;
77	  private readonly sweepBatchSize: number;
78	
79	  constructor(
80	    @InjectRepository(MailboxMessage)
81	    private readonly messageRepository: Repository<MailboxMessage>,
82	    @InjectRepository(User)
83	    private readonly userRepository: Repository<User>,
84	    @InjectDataSource()
85	    private readonly dataSource: DataSource,
86	    private readonly identityService: IdentityService,
87	    private readonly clock: Clock,
88	    configService: ConfigService
89	  ) {
90	    this.pendingCap = positiveIntConfig(configService.get('MAILBOX_PENDING_CAP'), 1000);
91	    this.pollLimit = positiveIntConfig(configService.get('MAILBOX_POLL_LIMIT'), 100);
92	    this.lockTimeoutMs = resolveAdvisoryLockTimeoutMs(configService);
93	    this.sweepBatchSize = positiveIntConfig(
94	      configService.get('MAILBOX_SWEEP_BATCH_SIZE'),
95	      DEFAULT_SWEEP_BATCH_SIZE
96	    );
97	  }
98	
99	  /**
100	   * Post a sealed blob to a recipient identity publicKey. The sender is the
101	   * authenticated account; only its hash feeds the idempotency scope, so no
102	   * durable sender→recipient graph is stored.
103	   *
104	   * Posts to unknown recipient pubkeys are rejected — the accepted,
105	   * rate-limited, exact-pubkey existence oracle (blueprint/api.md). The rate
106	   * limit lives at the HTTP edge (per-sender throttle); reaching this check at
107	   * all requires a valid access token, so only a real account can probe it.
108	   */
109	  async post(senderPublicKey: string, input: PostMessageInput): Promise<PostMessageResult> {
110	    const recipientPublicKey = this.identityService.normalizePublicKey(input.recipientPublicKey);
111	
112	    // Validate the payload before touching the oracle: a malformed request
113	    // must never learn whether the recipient exists.
114	    const blob = Buffer.from(input.blob, 'base64');
115	    if (blob.length > MAX_BLOB_BYTES) {
116	      throw new PayloadTooLargeException(`Sealed blob exceeds ${MAX_BLOB_BYTES} bytes`);
117	    }
118	
119	    const recipient = await this.userRepository.findOne({
120	      where: { publicKey: recipientPublicKey },
121	    });
122	    if (!recipient) {
123	      throw new NotFoundException('Unknown recipient');
124	    }
125	
126	    const idempotencyScope = this.scopeIdempotency(senderPublicKey, input.idempotencyKey);
127	
128	    // Fast path: an idempotent replay wins even when the mailbox is full, and
129	    // takes no lock — the common repost case never contends on the per-recipient
130	    // serialization below.
131	    const existing = await this.messageRepository.findOne({
132	      where: { recipientPublicKey, idempotencyScope },
133	    });
134	    if (existing) {
135	      return { id: existing.id };
136	    }
137	
138	    try {
139	      return await this.enforceCapAndInsert(recipientPublicKey, idempotencyScope, blob);
140	    } catch (error) {
141	      // The unique (recipient, idempotencyScope) index is the durable dedup
142	      // backstop under a concurrent double-post: a same-scope insert that races
143	      // past the in-transaction replay check aborts the transaction, so re-read
144	      // the committed winner on a fresh statement (outside the rolled-back txn).
145	      if (error instanceof QueryFailedError) {
146	        const winner = await this.messageRepository.findOne({
147	          where: { recipientPublicKey, idempotencyScope },
148	        });
149	        if (winner) {
150	          return { id: winner.id };
151	        }
152	      }
153	      throw error;
154	    }
155	  }
156	
157	  /**
158	   * The pending-cap enforcement window — purge → count → cap-check → insert —
159	   * run under a per-recipient transaction-scoped advisory lock so concurrent
160	   * posts to the SAME recipient serialize. Without the lock the count read and
161	   * the insert are separate statements: two writers arriving at `cap - 1` could
162	   * both observe `cap - 1`, both pass the check, and both insert, overshooting
163	   * the cap (a DoS control). Holding `pg_advisory_xact_lock` across the whole
164	   * transaction means the second writer blocks until the first commits, then
165	   * counts the first's committed row before its own check — the overshoot
166	   * closes structurally, no schema change required. The lock is transaction
167	   * scoped: Postgres releases it automatically on commit or rollback. The wait
168	   * is bounded by `lock_timeout` so sustained same-recipient contention cannot
169	   * fill the pool with blocked waiters (a timed-out waiter surfaces as a 503).
170	   */
171	  private async enforceCapAndInsert(
172	    recipientPublicKey: string,
173	    idempotencyScope: string,
174	    blob: Buffer
175	  ): Promise<PostMessageResult> {
176	    return this.dataSource.transaction(async (manager) => {
177	      await setAdvisoryLockTimeout(manager, this.lockTimeoutMs);
178	      await acquireAdvisoryLock(manager, this.recipientLockKey(recipientPublicKey));
179	      const repo = manager.getRepository(MailboxMessage);
180	
181	      // Re-check idempotency now that we hold the lock: a same-scope writer that
182	      // committed just ahead of us is visible here, so we return its row instead
183	      // of racing it to a unique-index violation.
184	      const replay = await repo.findOne({ where: { recipientPublicKey, idempotencyScope } });
185	      if (replay) {
186	        return { id: replay.id };
187	      }
188	
189	      // Re-verify the recipient still exists while holding the recipient lock,
190	      // not only at the unlocked oracle above: the account hard-delete cascade
191	      // holds this same key while it purges the mailbox and deletes the account,
192	      // so a post that raced the delete observes the committed deletion here and
193	      // fails closed rather than resurrecting a row for a gone account (mailbox
194	      // rows have no FK to cascade them). The lock (held until this transaction
195	      // commits) bars any delete between this re-check and the insert below.
196	      const recipient = await this.userRepository.findOne({
197	        where: { publicKey: recipientPublicKey },
198	      });
199	      if (!recipient) {
200	        throw new NotFoundException('Unknown recipient');
201	      }
202	
203	      // Expired rows are dead fuel: purge before counting so a full-of-expired
204	      // mailbox still accepts new mail (opportunistic housekeeping).
205	      await this.purgeExpired(recipientPublicKey, repo);
206	
207	      const pending = await repo.count({ where: { recipientPublicKey } });
208	      if (pending >= this.pendingCap) {
209	        throw new ConflictException('Recipient mailbox is full');
210	      }
211	
212	      const saved = await repo.save({
213	        recipientPublicKey,
214	        idempotencyScope,
215	        blob,
216	        receivedAt: this.clock.now(),
217	      });
218	      return { id: saved.id };
219	    });
220	  }
221	
222	  /**
223	   * Poll the caller mailbox: pending messages oldest-first, capped at the
224	   * poll limit. No sender metadata is returned in the clear — the sealed
225	   * payload carries the owner-signed sender inside.
226	   */
227	  async poll(recipientPublicKey: string): Promise<{ messages: PolledMessage[] }> {
228	    await this.purgeExpired(recipientPublicKey, this.messageRepository);
229	    const rows = await this.messageRepository.find({
230	      where: { recipientPublicKey },
231	      order: { receivedAt: 'ASC' },
232	      take: this.pollLimit,
233	    });
234	    return {
235	      messages: rows.map((row) => ({
236	        id: row.id,
237	        receivedAt: row.receivedAt.toISOString(),
238	        blob: Buffer.from(row.blob).toString('base64'),
239	      })),
240	    };
241	  }
242	
243	  /**
244	   * Ack = hard delete by id, scoped to the caller mailbox (AGENTS.md: never
245	   * persist crypto-bearing rows past their consumer). Idempotent and
246	   * leak-free: acking a gone or foreign id succeeds without side effects.
247	   */
248	  async ack(recipientPublicKey: string, id: string): Promise<{ success: boolean }> {
249	    // A malformed (non-uuid) id can never name a server-minted row, so short
250	    // out to the documented idempotent success WITHOUT querying Postgres —
251	    // otherwise the `uuid`-typed id column raises 22P02 (invalid input syntax
252	    // for uuid) and turns a well-behaved no-op into a 500.
253	    if (!UUID_RE.test(id)) {
254	      return { success: true };
255	    }
256	    await this.messageRepository.delete({ id, recipientPublicKey });
257	    return { success: true };
258	  }
259	
260	  private async purgeExpired(
261	    recipientPublicKey: string,
262	    repo: Repository<MailboxMessage>
263	  ): Promise<void> {
264	    const cutoff = new Date(this.clock.now().getTime() - TTL_MS);
265	    await repo.delete({ recipientPublicKey, receivedAt: LessThan(cutoff) });
266	  }
267	
268	  /**
269	   * The global, recipient-less TTL sweep the scheduled worker drives (#667): the
270	   * lazy `purgeExpired` only fires on a recipient's own post/poll, so a dormant
271	   * mailbox keeps expired rows forever. This makes the 90-day bound a hard
272	   * guarantee independent of activity.
273	   *
274	   * The cutoff is one Clock snapshot for the whole run (deterministic, testable),
275	   * and deletes are batched by `ctid` — bounded rows per statement, looping until
276	   * a short batch signals drained — so the sweep never takes a long table lock or
277	   * bloats a single transaction on a large backlog. It is safe to interleave with
278	   * post/poll/lazy purge: a concurrent post writes a fresh `received_at` (>=
279	   * cutoff) that this WHERE can never match, and a row another path already
280	   * deleted simply isn't re-counted. Overlap is prevented in-process by the
281	   * scheduler's in-flight guard (the republisher's mechanism); a cross-instance
282	   * overlap is harmless because the delete is idempotent. Returns the number of
283	   * rows deleted.
284	   */
285	  async sweepExpired(): Promise<number> {
286	    const cutoff = new Date(this.clock.now().getTime() - TTL_MS);
287	    let total = 0;
288	    for (let batch = 0; batch < SWEEP_MAX_BATCHES; batch += 1) {
289	      const deleted = await this.deleteExpiredBatch(cutoff);
290	      total += deleted;
291	      if (deleted < this.sweepBatchSize) {
292	        break;
293	      }
294	    }
295	    return total;
296	  }
297	
298	  /**
299	   * Delete up to one batch of globally-expired rows. Postgres has no
300	   * `DELETE ... LIMIT`, so the batch is bounded by selecting `ctid`s under the
301	   * cutoff and deleting exactly those; `received_at` ordering lets the
302	   * `idx_mailbox_received_at` index drive the scan. Returns the rows deleted.
303	   */
304	  private async deleteExpiredBatch(cutoff: Date): Promise<number> {
305	    const result = await this.messageRepository
306	      .createQueryBuilder()
307	      .delete()
308	      .from(MailboxMessage)
309	      .where(
310	        'ctid IN (SELECT ctid FROM mailbox_messages WHERE received_at < :cutoff ORDER BY received_at LIMIT :limit)',
311	        { cutoff, limit: this.sweepBatchSize }
312	      )
313	      .execute();
314	    return result.affected ?? 0;
315	  }
316	
317	  private scopeIdempotency(senderPublicKey: string, idempotencyKey: string): string {
318	    return createHash('sha256').update(`${senderPublicKey}:${idempotencyKey}`).digest('hex');
319	  }
320	
321	  /**
322	   * The per-recipient advisory-lock key over the ALREADY-normalized recipient
323	   * key. This MUST be the shared `advisoryLockKey` (not a private copy): the
324	   * account hard-delete cascade serializes against a concurrent post by taking
325	   * `advisoryLockKey(publicKey)`, so the two derive the recipient key from one
326	   * source — the resurrection guard is structural, not an asserted invariant.
327	   */
328	  private recipientLockKey(recipientPublicKey: string): bigint {
329	    return advisoryLockKey(recipientPublicKey);
330	  }
331	}
