1	import { ServiceUnavailableException } from '@nestjs/common';
2	import { ConfigService } from '@nestjs/config';
3	import { createHash } from 'node:crypto';
4	import { DataSource, EntityManager, QueryFailedError } from 'typeorm';
5	
6	/**
7	 * Default bound on how long an advisory-lock acquire may WAIT while holding its
8	 * pooled connection before it aborts and releases it. `pg_advisory_xact_lock`
9	 * blocks on a held connection, so an unbounded wait under sustained same-key
10	 * contention fills the shared pool with blocked waiters and starves unrelated
11	 * queries — the cap/refcount control degrades into a service-wide DoS.
12	 */
13	const DEFAULT_LOCK_TIMEOUT_MS = 3000;
14	
15	/** Postgres `lock_not_available`: a statement aborted by `lock_timeout`. */
16	const LOCK_NOT_AVAILABLE = '55P03';
17	
18	/**
19	 * Read the advisory-lock wait bound (ms) from config, failing closed to the
20	 * safe default for an unset OR garbage value. `0` is a valid explicit value —
21	 * it disables the bound (the pre-hardening, unbounded-wait behavior).
22	 */
23	export function resolveAdvisoryLockTimeoutMs(configService: ConfigService): number {
24	  const raw = configService.get<string | number>('DB_ADVISORY_LOCK_TIMEOUT_MS');
25	  if (raw === undefined || raw === null || String(raw).trim() === '') {
26	    return DEFAULT_LOCK_TIMEOUT_MS;
27	  }
28	  const value = Number(raw);
29	  return Number.isInteger(value) && value >= 0 ? value : DEFAULT_LOCK_TIMEOUT_MS;
30	}
31	
32	/**
33	 * Bound advisory-lock waits to `timeoutMs` for the current transaction. Call
34	 * once before acquiring any key; registry batches lock several keys under a
35	 * single bound. `set_config('lock_timeout', …, true)` is the transaction-local
36	 * (`is_local = true`) equivalent of `SET LOCAL`, taking the value as a bind
37	 * parameter. `0` leaves the wait unbounded.
38	 */
39	export async function setAdvisoryLockTimeout(
40	  manager: EntityManager,
41	  timeoutMs: number
42	): Promise<void> {
43	  if (timeoutMs > 0) {
44	    await manager.query('SELECT set_config($1, $2, true)', [
45	      'lock_timeout',
46	      Math.trunc(timeoutMs).toString(),
47	    ]);
48	  }
49	}
50	
51	/**
52	 * Acquire one transaction-scoped advisory lock, mapping a `lock_timeout` abort
53	 * to a retryable 503 so a contended caller degrades gracefully instead of
54	 * holding its connection until the pool starves. The lock auto-releases at
55	 * commit or rollback.
56	 */
57	export async function acquireAdvisoryLock(manager: EntityManager, key: bigint): Promise<void> {
58	  try {
59	    await manager.query('SELECT pg_advisory_xact_lock($1::bigint)', [key.toString()]);
60	  } catch (error) {
61	    if (isLockNotAvailable(error)) {
62	      throw new ServiceUnavailableException('Contended resource; retry shortly');
63	    }
64	    throw error;
65	  }
66	}
67	
68	/**
69	 * A Postgres `lock_not_available` (55P03) — a statement aborted by
70	 * `lock_timeout`, whether the advisory-lock acquire or a row lock taken later
71	 * under the same transaction-scoped bound. TypeORM wraps it as a
72	 * `QueryFailedError` carrying the driver code.
73	 */
74	export function isLockNotAvailable(error: unknown): boolean {
75	  if (!(error instanceof QueryFailedError)) {
76	    return false;
77	  }
78	  const code =
79	    (error.driverError as { code?: string } | undefined)?.code ??
80	    (error as unknown as { code?: string }).code;
81	  return code === LOCK_NOT_AVAILABLE;
82	}
83	
84	/**
85	 * Stable 64-bit advisory-lock key for an opaque token — a content CID, an IPNS
86	 * name, or a namespaced account key: the first 8 bytes of its sha256 read
87	 * big-endian as a signed 64-bit int for `pg_advisory_xact_lock($1::bigint)`.
88	 * The registry and the upload path MUST share this function so the same CID
89	 * locked from either serializes against the other.
90	 */
91	export function advisoryLockKey(token: string): bigint {
92	  return createHash('sha256').update(token).digest().readBigInt64BE(0);
93	}
94	
95	/**
96	 * Namespaced per-account advisory key: `account:` prevents any collision with a
97	 * bare CID or IPNS-name key in the shared bigint lock space. The upload quota
98	 * gate and the account hard-delete cascade MUST share this function so an
99	 * in-flight upload serializes against the account's deletion on the same key.
100	 */
101	export function accountLockKey(accountId: string): bigint {
102	  return advisoryLockKey(`account:${accountId}`);
103	}
104	
105	/**
106	 * Namespaced per-CID key for the SESSION lock that guards a durability window:
107	 * the upload path holds it across commit → pin, and retire (and the account
108	 * hard-delete cascade's post-commit unpin) holds it across commit → unpin.
109	 * DISTINCT from the plain CID xact lock so the upload can hold both — session
110	 * lock on its own connection, xact lock on the tx connection — without a
111	 * same-key self-deadlock. Upload and retire MUST share this key so retire's
112	 * post-commit unpin of a CID serializes against a concurrent upload re-pinning
113	 * the same CID (#714).
114	 */
115	export function pinDurabilityLockKey(cid: string): bigint {
116	  return advisoryLockKey(`pin-durability:${cid}`);
117	}
118	
119	/**
120	 * Acquire a batch of transaction-scoped advisory locks in one round-trip and one
121	 * deadlock-free order: keys are de-duplicated and sorted, so any two overlapping
122	 * batches take their shared keys in the same sequence and cannot form a cycle.
123	 * Acquisition order comes SOLELY from the pre-sorted `sorted` array: Postgres
124	 * evaluates each `pg_advisory_xact_lock(k)` as it scans `unnest` in array order,
125	 * BEFORE the sort node runs — so the `ORDER BY k` does NOT co-guarantee ascending
126	 * acquisition and the pre-sort must never be dropped in reliance on it. A
127	 * `lock_timeout` abort on any key maps to the retryable 503. Set the bound
128	 * (setAdvisoryLockTimeout) once before calling.
129	 */
130	export async function acquireAdvisoryLocks(manager: EntityManager, keys: bigint[]): Promise<void> {
131	  const sorted = [...new Set(keys)].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
132	  if (sorted.length === 0) {
133	    return;
134	  }
135	  try {
136	    await manager.query(
137	      'SELECT pg_advisory_xact_lock(k) FROM unnest($1::bigint[]) AS k ORDER BY k',
138	      [sorted.map((key) => key.toString())]
139	    );
140	  } catch (error) {
141	    if (isLockNotAvailable(error)) {
142	      throw new ServiceUnavailableException('Contended resource; retry shortly');
143	    }
144	    throw error;
145	  }
146	}
147	
148	/**
149	 * Run `work` in a transaction, mapping any `lock_timeout` abort (55P03) — the
150	 * advisory acquire OR any row lock taken later under the same bound — to the
151	 * retryable 503, so a contended caller degrades gracefully instead of escaping
152	 * as a 500. A 503 an inner helper already raised passes through unchanged.
153	 */
154	export async function runLockGuardedTransaction<T>(
155	  dataSource: DataSource,
156	  work: (manager: EntityManager) => Promise<T>
157	): Promise<T> {
158	  try {
159	    return await dataSource.transaction(work);
160	  } catch (error) {
161	    if (isLockNotAvailable(error)) {
162	      throw new ServiceUnavailableException('Contended resource; retry shortly');
163	    }
164	    throw error;
165	  }
166	}
167	
168	/**
169	 * Run `work` while holding a SESSION-level advisory lock on `key`, on a
170	 * dedicated connection held for the whole span and released in a `finally`.
171	 * Unlike the xact lock (auto-released at COMMIT), a session lock spans several
172	 * transactions PLUS an external side effect — the caller uses it to serialize a
173	 * commit → external effect → compensation window that a xact lock would leave
174	 * unguarded once it releases at commit. A `lock_timeout` abort maps to the
175	 * retryable 503; the bound is set session-local on the dedicated connection and
176	 * RESET before release so it never leaks to the next pool borrower.
177	 */
178	export async function withSessionAdvisoryLock<T>(
179	  dataSource: DataSource,
180	  key: bigint,
181	  timeoutMs: number,
182	  work: () => Promise<T>
183	): Promise<T> {
184	  const runner = dataSource.createQueryRunner();
185	  await runner.connect();
186	  const bounded = timeoutMs > 0;
187	  try {
188	    if (bounded) {
189	      await runner.query('SELECT set_config($1, $2, false)', [
190	        'lock_timeout',
191	        Math.trunc(timeoutMs).toString(),
192	      ]);
193	    }
194	    let acquired = false;
195	    try {
196	      await runner.query('SELECT pg_advisory_lock($1::bigint)', [key.toString()]);
197	      acquired = true;
198	      return await work();
199	    } catch (error) {
200	      if (isLockNotAvailable(error)) {
201	        throw new ServiceUnavailableException('Contended resource; retry shortly');
202	      }
203	      throw error;
204	    } finally {
205	      // Unlock failure implies a dead connection, whose session lock Postgres
206	      // has already dropped — the pool discards it on release.
207	      if (acquired) {
208	        await runner.query('SELECT pg_advisory_unlock($1::bigint)', [key.toString()]).catch(() => {
209	          /* noop */
210	        });
211	      }
212	    }
213	  } finally {
214	    if (bounded) {
215	      await runner.query('RESET lock_timeout').catch(() => {
216	        /* noop */
217	      });
218	    }
219	    await runner.release();
220	  }
221	}
