20	/**
21	 * Serialize every refcount/inventory mutation for each token by taking a
22	 * transaction-scoped advisory lock. Row locks can't see an unborn INSERT, so
23	 * only a per-token lock closes the register/retire phantom race and concurrent
24	 * duplicate inserts. Keys are acquired in sorted order so overlapping batches
25	 * cannot deadlock; the lock auto-releases at commit or rollback. One
26	 * `lock_timeout` bound covers the whole batch so a contended waiter aborts and
27	 * releases its pooled connection (surfacing as a 503) instead of holding it.
28	 */
29	async function lockTokens(
30	  manager: EntityManager,
31	  tokens: string[],
32	  timeoutMs: number
33	): Promise<void> {
34	  await setAdvisoryLockTimeout(manager, timeoutMs);
35	  await acquireAdvisoryLocks(manager, tokens.map(advisoryLockKey));
36	}
