60	/**
61	 * The pin/name registry (blueprint/api.md, Pin/name registry) — the one
62	 * surface every publish flow traverses. It is deliberately dumb bookkeeping:
63	 * per-account rows, idempotent upserts, union liveness, and a per-account
64	 * quota sum. It authorizes nothing across accounts and holds no state a
65	 * client cannot rebuild from the network.
66	 *
67	 * Determinism/side-effects are injected: the physical unpin rides the
68	 * [`PinStore`] seam, never a direct Kubo call in this logic.
69	 */
70	@Injectable()
71	export class RegistryService {
72	  private readonly defaultLimitBytes: bigint;
73	  private readonly lockTimeoutMs: number;
74	  private readonly logger = new Logger(RegistryService.name);
75	
76	  constructor(
77	    @InjectRepository(PinnedCid)
78	    private readonly pinRepository: Repository<PinnedCid>,
79	    @InjectRepository(User)
80	    private readonly userRepository: Repository<User>,
81	    @InjectDataSource()
82	    private readonly dataSource: DataSource,
83	    private readonly pinStore: PinStore,
84	    configService: ConfigService
85	  ) {
86	    this.defaultLimitBytes = byteConfigBigInt(
87	      configService.get('QUOTA_DEFAULT_BYTES'),
88	      DEFAULT_QUOTA_BYTES
89	    );
90	    this.lockTimeoutMs = resolveAdvisoryLockTimeoutMs(configService);
91	  }
92	
93	  /**
94	   * Batch register `[{ipnsName, headCid?, contentCids[]}]` under the caller's
95	   * account. Register-first, fail-closed: each entry upserts its name-inventory
96	   * row BEFORE any content pin row, so content is never accepted without the
97	   * name that anchors it. Every upsert is idempotent — a replayed batch (name
98	   * waves re-reference the same CIDs) changes nothing.
99	   */
100	  async register(accountId: string, entries: RegisterEntry[]): Promise<RegisterResult> {
101	    // Collapse the batch to its distinct writes; the last-provided head wins
102	    // per name, matching the sequential upsert semantics.
103	    const heads = new Map<string, string | undefined>();
104	    const nameOrder: string[] = [];
105	    const cidOrder: string[] = [];
106	    const cids = new Set<string>();
107	    for (const entry of entries) {
108	      if (!heads.has(entry.ipnsName)) {
109	        nameOrder.push(entry.ipnsName);
110	        heads.set(entry.ipnsName, undefined);
111	      }
112	      if (entry.headCid !== undefined) {
113	        heads.set(entry.ipnsName, entry.headCid);
114	      }
115	      for (const cid of [...(entry.headCid ? [entry.headCid] : []), ...entry.contentCids]) {
116	        if (!cids.has(cid)) {
117	          cids.add(cid);
118	          cidOrder.push(cid);
119	        }
120	      }
121	    }
122	
123	    // All-or-nothing: register-first, fail-closed means a mid-batch error must
124	    // leave no partial state behind.
125	    if (nameOrder.length > 0 || cidOrder.length > 0) {
126	      await runLockGuardedTransaction(this.dataSource, async (manager) => {
127	        // Serialize per token before any read/write: register and retire
128	        // contend on the same keys, closing the phantom-INSERT race and
129	        // concurrent-duplicate inserts.
130	        await lockTokens(manager, [...nameOrder, ...cidOrder], this.lockTimeoutMs);
131	
132	        // Read BYO under a users-row lock: register and setByo contend on the
133	        // same existing row, so a row lock (not the token advisory lock) keeps
134	        // a concurrent toggle from stamping new pins with a stale advisory flag.
135	        const user = await manager.getRepository(User).findOne({
136	          where: { id: accountId },
137	          lock: { mode: 'pessimistic_write' },
138	        });
139	        if (!user) {
140	          throw new UnauthorizedException('Unknown account');
141	        }
142	        const advisory = user.byo;
143	
144	        const nameRepo = manager.getRepository(NameInventory);
145	        const pinRepo = manager.getRepository(PinnedCid);
146	
147	        // Names first: content is never accepted without its anchoring name.
148	        const existingNames = nameOrder.length
149	          ? await nameRepo.find({ where: { accountId, ipnsName: In(nameOrder) } })
150	          : [];
151	        const nameByKey = new Map(existingNames.map((row) => [row.ipnsName, row]));
152	        const nameWrites: Partial<NameInventory>[] = [];
153	        for (const ipnsName of nameOrder) {
154	          const head = heads.get(ipnsName);
155	          const existing = nameByKey.get(ipnsName);
156	          if (existing) {
157	            // A bare re-register (no head) leaves the head untouched.
158	            if (head !== undefined && existing.headCid !== head) {
159	              existing.headCid = head;
160	              nameWrites.push(existing);
161	            }
162	          } else {
163	            nameWrites.push({ accountId, ipnsName, headCid: head ?? null });
164	          }
165	        }
166	        if (nameWrites.length) {
167	          await nameRepo.save(nameWrites);
168	        }
169	
170	        const existingPins = cidOrder.length
171	          ? await pinRepo.find({ where: { accountId, cid: In(cidOrder) } })
172	          : [];
173	        const knownCids = new Set(existingPins.map((row) => row.cid));
174	        // Idempotent: a CID already counted keeps its size and advisory origin.
175	        const pinWrites = cidOrder
176	          .filter((cid) => !knownCids.has(cid))
177	          .map((cid) => ({ accountId, cid, size: '0', advisory }));
178	        if (pinWrites.length) {
179	          await pinRepo.save(pinWrites);
180	        }
181	      });
182	    }
183	
184	    // `names` is the distinct-name count (the DTO contract), not the raw batch
185	    // length, which double-counts a name repeated across entries.
186	    return { names: nameOrder.length, cids: cids.size };
187	  }
188	
189	  /**
190	   * Batch retire `[ipnsName | cid]` for the caller's account. A target may be
191	   * either a name or a CID; the API is zero-knowledge about which, so it
192	   * removes the caller's matching row from BOTH tables (their namespaces do
193	   * not collide). Union liveness: a retired CID is physically unpinned only
194	   * when the LAST account's row for it is gone (global refcount zero).
195	   */
196	  async retire(accountId: string, targets: string[]): Promise<RetireResult> {
197	    if (targets.length === 0) {
198	      return { retired: 0, unpinned: 0 };
199	    }
200	
201	    // All-or-nothing, and serialized per CID against concurrent register and
202	    // retire: the advisory lock (not a row lock, which can't see an unborn
203	    // INSERT) makes the delete → survivor check the authority for unpinning.
204	    const { retired, unpinCids } = await runLockGuardedTransaction(
205	      this.dataSource,
206	      async (manager) => {
207	        await lockTokens(manager, targets, this.lockTimeoutMs);
208	
209	        const nameRepo = manager.getRepository(NameInventory);
210	        const pinRepo = manager.getRepository(PinnedCid);
211	
212	        const held = await pinRepo.find({ where: { accountId, cid: In(targets) } });
213	        const heldByCaller = new Set(held.map((row) => row.cid));
214	        const heldCids = targets.filter(
215	          (target, index) => targets.indexOf(target) === index && heldByCaller.has(target)
216	        );
217	
218	        const nameDeleted = await nameRepo.delete({ accountId, ipnsName: In(targets) });
219	        const pinDeleted = await pinRepo.delete({ accountId, cid: In(targets) });
220	
221	        // Under the lock, a held CID with no surviving row is at global zero.
222	        const survivors = heldCids.length
223	          ? await pinRepo.find({ where: { cid: In(heldCids) } })
224	          : [];
225	        const surviving = new Set(survivors.map((row) => row.cid));
226	
227	        return {
228	          retired: (nameDeleted.affected ?? 0) + (pinDeleted.affected ?? 0),
229	          unpinCids: heldCids.filter((cid) => !surviving.has(cid)),
230	        };
231	      }
232	    );
233	
234	    // Fire the external unpin after commit — never hold the txn across Kubo.
235	    // The retire txn's per-token xact lock releases at commit, so between it and
236	    // this unpin a concurrent upload can re-pin the same CID under the upload
237	    // path's `pin-durability:` session lock, commit a row, and return success —
238	    // an unguarded unpin here would then delete freshly-pinned, durably-held
239	    // bytes (#714). Re-serialize on that SAME session key and recount under it:
240	    // if a survivor row now exists the bytes are legitimately held, so skip.
241	    //
242	    // The destructive work — the row deletes — is already committed, so `retired`
243	    // is authoritative and must stay observable. unpin is best-effort (PinStore
244	    // contract: a failed unpin never fails a retire; the CID decays via GC), so a
245	    // per-CID durability lock that is contended here — almost always a concurrent
246	    // upload re-pinning that same CID — leaves the CID pinned and moves on,
247	    // rather than discarding the committed result behind a misleading 503 (#723).
248	    let unpinned = 0;
249	    for (const cid of unpinCids) {
250	      try {
251	        const didUnpin = await withSessionAdvisoryLock(
252	          this.dataSource,
253	          pinDurabilityLockKey(cid),
254	          this.lockTimeoutMs,
255	          async () => {
256	            const survivors = await this.pinRepository.find({ where: { cid } });
257	            if (survivors.length > 0) {
258	              return false;
259	            }
260	            // Count only seam-confirmed releases; a no-op/swallowed unpin (Kubo
261	            // hiccup, unconfigured store) returns false and must not be counted.
262	            return this.pinStore.unpin(cid);
263	          }
264	        );
265	        if (didUnpin) {
266	          unpinned += 1;
267	        }
268	      } catch (error) {
269	        // The row deletes already committed and `retired` is authoritative; the
270	        // post-commit unpin is best-effort (PinStore contract), so no failure
271	        // here — lock contention or otherwise — may turn a retire into a 500.
272	        this.logger.warn(`retire left ${cid} pinned for GC: ${String(error)}`);
273	      }
274	    }
275	
276	    return { retired, unpinned };
277	  }
278	
279	  /**
280	   * The per-account quota (blueprint/api.md). `usedBytes` is the sum over the
281	   * account's pin rows; `limitBytes` is the per-account override, else the env
282	   * default. Hosted accounts are authoritative (`advisory: false`, the sum
283	   * gates uploads); a BYO account's rows are advisory (`advisory: true`, quota
284	   * always allows) — the bytes live on the user's own provider.
285	   */
286	  async quota(accountId: string): Promise<QuotaResult> {
287	    const user = await this.userRepository.findOne({ where: { id: accountId } });
288	    if (!user) {
289	      throw new UnauthorizedException('Unknown account');
290	    }
291	
292	    // Compute in BigInt (exact above 2^53) and narrow to the wire number at the
293	    // edge; the DTO is a JSON number, but the gate math never rounds (#677).
294	    const used = await sumPinnedBytes(this.pinRepository, accountId);
295	    const limit = resolveLimitBytes(user.quotaLimitOverride, this.defaultLimitBytes);
296	
297	    return {
298	      usedBytes: Number(used),
299	      limitBytes: Number(limit),
300	      advisory: user.byo,
301	    };
302	  }
303	
304	  /** Toggle the account's BYO flag; new pin rows are advisory while set. */
305	  async setByo(accountId: string, byo: boolean): Promise<{ byo: boolean }> {
306	    const result = await this.userRepository.update({ id: accountId }, { byo });
307	    if (!result.affected) {
308	      throw new UnauthorizedException('Unknown account');
309	    }
310	    return { byo };
311	  }
312	}
