35	/**
36	 * Max uploads admitted concurrently to the pin path (`CONTENT_PIN_CONCURRENCY`).
37	 * Each admitted upload holds one pooled DB connection (the session lock) across
38	 * its ~30s Kubo pin, and transiently a second (the Phase-2 tx) — so a pin burst
39	 * could otherwise tie up the whole pool and 503 unrelated routes.
40	 */
41	const DEFAULT_PIN_CONCURRENCY = 4;
42	
43	export interface ResolvedPinConcurrency {
44	  ceiling: number;
45	  /** The configured value before clamping, when it had to be lowered. */
46	  clampedFrom?: number;
47	}
48	
49	/**
50	 * The pin-admission ceiling, clamped so `2 × ceiling ≤ poolSize` always holds
51	 * (an admitted upload holds its session-lock connection across the pin AND
52	 * borrows a second for the commit tx, so it needs 2 pooled connections to make
53	 * progress). Deriving the ceiling from the pool size makes that invariant
54	 * structural — config drift (an over-large ceiling) can no longer silently
55	 * reintroduce pool exhaustion. A pool of 1 cannot host even one upload without
56	 * self-deadlocking on its second connection, so the safe max floors to 0 there
57	 * and the pin path is refused (upload() fails closed) rather than deadlocked.
58	 */
59	export function resolvePinConcurrency(configService: ConfigService): ResolvedPinConcurrency {
60	  const raw = configService.get<string | number>('CONTENT_PIN_CONCURRENCY');
61	  let configured = DEFAULT_PIN_CONCURRENCY;
62	  if (raw !== undefined && raw !== null && String(raw).trim() !== '') {
63	    const value = Number(raw);
64	    if (Number.isInteger(value) && value >= 1) {
65	      configured = value;
66	    }
67	  }
68	  const safeMax = Math.floor(resolveDbPoolSize(configService) / 2);
69	  const ceiling = Math.min(configured, safeMax);
70	  return ceiling < configured ? { ceiling, clampedFrom: configured } : { ceiling };
71	}
72	
73	/**
74	 * A stored pin outcome. `created` drives the durable pin — true both when this
75	 * upload inserted a fresh row and when it PROMOTED a registry-only row (size 0,
76	 * never hosted-pinned) to a real hosted pin. `promoted` tells compensation to
77	 * revert just the size charge on that pre-existing row rather than delete it.
78	 */
79	interface RegisterOutcome {
80	  cid: string;
81	  size: number;
82	  created: boolean;
83	  promoted: boolean;
84	}
85	
86	export interface UploadResult {
87	  cid: string;
88	  size: number;
89	}
90	
91	/**
92	 * The hosted ingress upload path (blueprint/api.md, Content plane): pin opaque
93	 * bytes to CipherBox Kubo, quota-gated, registering the pin row in the same
94	 * traversal. The API is zero-knowledge — it pins bytes it never inspects. Only
95	 * hosted accounts may ingress here: a BYO account pins to its own provider and
96	 * its bytes bypass the API, so a BYO upload is refused (409) rather than pinned
97	 * to hosted Kubo off the quota's books.
98	 *
99	 * Concurrency (two shared resources under contention):
100	 *  - the per-account quota SUM — a check-then-act serialized by a per-account
101	 *    advisory lock so two concurrent uploads cannot both pass at the limit;
102	 *  - the per-CID pin refcount — serialized by the SAME per-CID advisory lock
103	 *    the registry's register/retire take, so an insert here can never race an
104	 *    unpin there. Both keys acquire in one sorted batch (deadlock-free).
105	 *
106	 * A register-only row (CID membership recorded at size 0 with no hosted bytes)
107	 * is NOT a completed pin: an upload of the matching bytes promotes it — pinning
108	 * and charging it — rather than trusting content Kubo never held.
109	 *
110	 * The DB transaction is the source of truth; the durable Kubo pin fires AFTER
111	 * commit. Byte-pin + row register stay all-or-nothing: a post-commit pin failure
112	 * compensates by retiring a row it inserted, or reverting a promoted row's size
113	 * charge (the pre-existing registration survives). A per-CID SESSION lock
114	 * (distinct `pin-durability:` key) spans commit → pin → compensate, so the in-tx
115	 * xact lock releasing at commit cannot let a concurrent same-CID upload observe
116	 * a committed row whose pin is still pending and return success for bytes that
117	 * were never durably pinned.
118	 */
119	@Injectable()
120	export class ContentService {
121	  private readonly logger = new Logger(ContentService.name);
122	  private readonly defaultLimitBytes: bigint;
123	  private readonly lockTimeoutMs: number;
124	  /** Bounds concurrent pin-path connections so the pin can't starve the pool. */
125	  private readonly pinSlots: Semaphore;
126	  /** 0 when the pool is too small (< 2) to host one upload — the path fails closed. */
127	  private readonly pinCeiling: number;
128	
129	  constructor(
130	    @InjectDataSource()
131	    private readonly dataSource: DataSource,
132	    private readonly pinStore: PinStore,
133	    configService: ConfigService
134	  ) {
135	    this.defaultLimitBytes = byteConfigBigInt(
136	      configService.get('QUOTA_DEFAULT_BYTES'),
137	      DEFAULT_QUOTA_BYTES
138	    );
139	    this.lockTimeoutMs = resolveAdvisoryLockTimeoutMs(configService);
140	    const pinConcurrency = resolvePinConcurrency(configService);
141	    this.pinCeiling = pinConcurrency.ceiling;
142	    if (pinConcurrency.ceiling === 0) {
143	      this.logger.error(
144	        'DB pool too small for the content pin path (needs DB_POOL_SIZE >= 2); hosted uploads will be refused with 503'
145	      );
146	    } else if (pinConcurrency.clampedFrom !== undefined) {
147	      this.logger.warn(
148	        `CONTENT_PIN_CONCURRENCY=${pinConcurrency.clampedFrom} exceeds the safe bound for the DB pool; clamped to ${pinConcurrency.ceiling} to preserve pool headroom`
149	      );
150	    }
151	    this.pinSlots = new Semaphore(pinConcurrency.ceiling);
152	  }
153	
154	  async upload(accountId: string, bytes: Buffer): Promise<UploadResult> {
155	    // Fail closed on a pool too small (< 2 connections) to host one upload: the
156	    // pin path needs its session-lock connection AND a second for the commit tx,
157	    // so admitting a request here would self-deadlock waiting for the second.
158	    if (this.pinCeiling === 0) {
159	      throw new ServiceUnavailableException('Content pin path unavailable; DB pool too small');
160	    }
161	    const size = bytes.byteLength;
162	    // Phase 1 — derive the CID with no durable side effect (only-hash), so the
163	    // ledger below can key on it before any bytes are pinned.
164	    const cid = await this.pinStore.hash(bytes);
165	
166	    // Admit at most `pinSlots` uploads into the session-lock → pin → compensate
167	    // span at once. That span holds a pooled connection across the external pin,
168	    // so an unbounded burst would otherwise exhaust the DB pool; the ceiling
169	    // reserves connections for every other route while the pin is in flight.
170	    return this.pinSlots.run(() =>
171	      // Serialize the whole commit → pin → compensate span per CID with a
172	      // session lock, so a concurrent same-CID upload cannot observe a
173	      // committed-but-not-yet-pinned row and return success for it (the in-tx
174	      // xact lock releases at commit, too early to cover the post-commit pin).
175	      withSessionAdvisoryLock(this.dataSource, pinDurabilityLockKey(cid), this.lockTimeoutMs, () =>
176	        this.registerAndPin(accountId, cid, size, bytes)
177	      )
178	    );
179	  }
180	
181	  private async registerAndPin(
182	    accountId: string,
183	    cid: string,
184	    size: number,
185	    bytes: Buffer
186	  ): Promise<UploadResult> {
187	    // Phase 2 — the source of truth: gate + register under the account and CID
188	    // advisory locks, atomically.
189	    const outcome = await runLockGuardedTransaction(this.dataSource, (manager) =>
190	      this.registerPin(manager, accountId, cid, size)
191	    );
192	
193	    // Phase 3 — durable pin AFTER commit. Byte-pin + register are all-or-nothing:
194	    // a pin failure (or a CID mismatch) compensates — retiring a row it inserted,
195	    // or reverting a promoted row's size charge.
196	    if (outcome.created) {
197	      let pinnedCid: string;
198	      try {
199	        pinnedCid = await this.pinStore.pin(bytes);
200	      } catch {
201	        await this.compensate(accountId, cid, outcome.promoted);
202	        throw new ServiceUnavailableException('Pin store unavailable; upload not durable');
203	      }
204	      if (pinnedCid !== cid) {
205	        // Fail closed: the row keys on `cid`; a mismatch means Kubo pinned bytes
206	        // under a different CID than the ledger references.
207	        await this.compensate(accountId, cid, outcome.promoted);
208	        throw new ServiceUnavailableException('Pin CID mismatch; upload rejected');
209	      }
210	    }
211	
212	    return { cid: outcome.cid, size: outcome.size };
213	  }
214	
215	  private async registerPin(
216	    manager: EntityManager,
217	    accountId: string,
218	    cid: string,
219	    size: number
220	  ): Promise<RegisterOutcome> {
221	    await setAdvisoryLockTimeout(manager, this.lockTimeoutMs);
222	    // Account key serializes the quota check-then-act; the CID key serializes the
223	    // pin-row insert against a concurrent register/retire of the same CID.
224	    await acquireAdvisoryLocks(manager, [accountLockKey(accountId), advisoryLockKey(cid)]);
225	
226	    const userRepo = manager.getRepository(User);
227	    const pinRepo = manager.getRepository(PinnedCid);
228	
229	    // Read BYO under a users-row lock (FOR UPDATE), the same synchronization
230	    // point registry.register uses: setByo toggles the flag with a bare UPDATE
231	    // that takes no advisory lock, so only the row lock serializes it against
232	    // this read. Without it a concurrent PATCH /account/byo could commit true
233	    // after an unlocked read of false and let a BYO account pin to hosted Kubo,
234	    // or commit false after a read of true and 409 a valid hosted upload.
235	    const user = await userRepo.findOne({
236	      where: { id: accountId },
237	      lock: { mode: 'pessimistic_write' },
238	    });
239	    if (!user) {
240	      throw new UnauthorizedException('Unknown account');
241	    }
242	    // Fail closed at hosted ingress for a BYO account: its bytes belong on its
243	    // own provider and bypass the API (blueprint/api.md, Content plane). Pinning
244	    // them to hosted Kubo off an advisory, uncounted row would be free hosted
245	    // storage, so refuse rather than pin. The row lock above makes this read and
246	    // the quota gate below atomic w.r.t. setByo, so a hosted upload past this
247	    // point always registers an AUTHORITATIVE (advisory=false) row.
