4	/**
5	 * The hosted pin-store port (blueprint/api.md, Content plane + "physical unpin
6	 * fires at global refcount zero" — v1's `guardedUnpin` survives). It owns every
7	 * side effect against CipherBox Kubo: computing a content CID, durably pinning
8	 * bytes on the ingress path, and releasing bytes at refcount zero. The registry
9	 * and content services own the row DECISIONS; this port owns the byte effects.
10	 *
11	 * `unpin` is a best-effort liveness optimization, not a correctness dependency:
12	 * the per-account row bookkeeping is the source of truth, so a failed or
13	 * unconfigured unpin never fails a retire — the CID lingers and decays from the
14	 * pin store's own GC. It returns whether the CID was physically released (`true`)
15	 * so callers report a truthful unpin count; a no-op or swallowed failure returns
16	 * `false` (never throws). `hash`/`pin` are the ingress byte path; a consumer that
17	 * only retires (the registry) never calls them, so the base rejects rather than
18	 * forcing every unpin-only fake to stub the byte methods.
19	 */
20	@Injectable()
21	export abstract class PinStore {
22	  abstract unpin(cid: string): Promise<boolean>;
23	
24	  /** Content CID of `bytes` with no durable pin (the pre-commit CID derivation). */
25	  hash(_bytes: Uint8Array): Promise<string> {
26	    throw new ServiceUnavailableException('Hosted pin store does not support content hashing');
27	  }
28	
29	  /** Durably pin `bytes`, returning the pinned CID (the post-commit byte effect). */
30	  pin(_bytes: Uint8Array): Promise<string> {
31	    throw new ServiceUnavailableException('Hosted pin store does not support pinning');
32	  }
33	}
34	
35	/** One Kubo `add` result line: `{ Name, Hash, Size }` (Size is a decimal string). */
36	interface KuboAddResult {
37	  Hash: string;
38	  Size: string;
39	}
