41	/**
42	 * Default hosted implementation over the Kubo RPC API (`KUBO_API_URL`). `hash`
43	 * and `pin` share identical `add` parameters so the pre-commit CID always
44	 * matches the pinned CID (content addressing is deterministic). `unpin` no-ops
45	 * when Kubo is unconfigured (unit tests, BYO-only deployments); the byte path
46	 * fails closed instead, since an upload with no pin store cannot be durable.
47	 */
48	@Injectable()
49	export class KuboPinStore extends PinStore {
50	  private readonly logger = new Logger(PinStore.name);
51	  private readonly apiUrl: string | undefined;
52	
53	  constructor(configService: ConfigService) {
54	    super();
55	    const raw = configService.get<string>('KUBO_API_URL');
56	    this.apiUrl = raw && raw.trim() ? raw.replace(/\/+$/, '') : undefined;
57	  }
58	
59	  override async hash(bytes: Uint8Array): Promise<string> {
60	    // `only-hash` chunks and hashes without writing blocks — no durable effect.
61	    return (await this.add(bytes, 'only-hash=true')).Hash;
62	  }
63	
64	  override async pin(bytes: Uint8Array): Promise<string> {
65	    return (await this.add(bytes, 'pin=true')).Hash;
66	  }
67	
68	  async unpin(cid: string): Promise<boolean> {
69	    if (!this.apiUrl) {
70	      return false;
71	    }
72	    try {
73	      const response = await fetch(
74	        `${this.apiUrl}/api/v0/pin/rm?arg=${encodeURIComponent(cid)}&recursive=true`,
75	        { method: 'POST', signal: AbortSignal.timeout(5000) }
76	      );
77	      if (!response.ok) {
78	        this.logger.warn(`pin/rm for ${cid} returned ${response.status}`);
79	        return false;
80	      }
81	      return true;
82	    } catch (error) {
83	      // Best-effort: bookkeeping already dropped the row, so a Kubo hiccup
84	      // must not fail the caller's retire. Log and report no physical release.
85	      this.logger.warn(`pin/rm failed for ${cid}: ${String(error)}`);
86	      return false;
87	    }
88	  }
89	
90	  private async add(bytes: Uint8Array, params: string): Promise<KuboAddResult> {
91	    if (!this.apiUrl) {
92	      throw new ServiceUnavailableException('Hosted pin store not configured');
93	    }
94	    const form = new FormData();
95	    // Copy into an ArrayBuffer-backed view so the Blob part type is exact. Kubo
96	    // requires the part to carry a filename, so pass one explicitly.
97	    form.append('file', new Blob([new Uint8Array(bytes)]), 'blob');
98	    const response = await fetch(`${this.apiUrl}/api/v0/add?${params}`, {
99	      method: 'POST',
100	      body: form,
101	      signal: AbortSignal.timeout(30_000),
102	    });
103	    if (!response.ok) {
104	      throw new ServiceUnavailableException(`Kubo add failed: ${response.status}`);
105	    }
106	    // Kubo streams newline-delimited JSON; a single file yields one final object.
107	    const lines = (await response.text()).trim().split('\n').filter(Boolean);
108	    const last = lines[lines.length - 1];
109	    if (!last) {
110	      throw new ServiceUnavailableException('Kubo add returned no result');
111	    }
112	    return JSON.parse(last) as KuboAddResult;
113	  }
114	}
